package com.example.flashcardapp.main;

import android.os.Bundle;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;
import androidx.lifecycle.lifecycleScope;

import com.example.flashcardapp.R;
import com.example.flashcardapp.data.Flashcard;
import com.example.flashcardapp.data.FlashcardRepository;
import com.example.flashcardapp.data.FlashcardRoomDatabase;

import kotlinx.coroutines.Dispatchers;
import kotlinx.coroutines.launch;
import kotlinx.coroutines.withContext;

public class AddFlashcardActivity extends AppCompatActivity {

    private EditText etQuestion, etAnswer;
    private Button btnSave;

    // Remove the old FlashcardDAO references.
    // We'll use the Room-based repository instead.
    private FlashcardRepository flashcardRepository;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_add_flashcard);

        etQuestion = findViewById(R.id.et_question);
        etAnswer = findViewById(R.id.et_answer);
        btnSave = findViewById(R.id.btn_save);

        // Use the new approach with Room
        flashcardRepository = new FlashcardRepository(
            FlashcardRoomDatabase.getDatabase(getApplicationContext()).flashcardDao()
        );

        btnSave.setOnClickListener(v -> {
            String question = etQuestion.getText().toString().trim();
            String answer = etAnswer.getText().toString().trim();

            if (!question.isEmpty() && !answer.isEmpty()) {
                // Insert using coroutine
                lifecycleScope.launch {
                    Flashcard newFlashcard = new Flashcard(0, question, answer, 2.5, 0, 1, System.currentTimeMillis(), "", "", null);
                    long rowId;
                    // Switch to IO dispatcher:
                    rowId = withContext(Dispatchers.IO) {
                        return@withContext flashcardRepository.insertFlashcard(newFlashcard);
                    };
                    withContext(Dispatchers.Main) {
                        Toast.makeText(AddFlashcardActivity.this, "Flashcard saved!", Toast.LENGTH_SHORT).show();
                        finish();
                    }
                };
            } else {
                Toast.makeText(this, "Please enter both question and answer.", Toast.LENGTH_SHORT).show();
            }
        });
    }
}

