package com.example.flashcardapp.main;

import android.os.Bundle;
import android.widget.ToggleButton;
import androidx.appcompat.app.AppCompatActivity;
import androidx.lifecycle.lifecycleScope;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.example.flashcardapp.R;
import com.example.flashcardapp.data.Flashcard;
import com.example.flashcardapp.data.FlashcardRepository;
import com.example.flashcardapp.data.FlashcardRoomDatabase;

import java.util.ArrayList;
import java.util.List;

import kotlinx.coroutines.Dispatchers;
import kotlinx.coroutines.launch;
import kotlinx.coroutines.withContext;

public class ListFlashcardsActivity extends AppCompatActivity {

    private ToggleButton toggleReviewTime;
    private List<Flashcard> flashcards;
    private FlashcardAdapter flashcardAdapter;

    // Use the Room-based repository instead of old FlashcardDAO.
    private FlashcardRepository flashcardRepository;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_list_flashcards);

        toggleReviewTime = findViewById(R.id.toggle_review_time);
        flashcards = new ArrayList<>();
        flashcardAdapter = new FlashcardAdapter(this, flashcards);

        RecyclerView recyclerView = findViewById(R.id.recycler_view_flashcards);
        recyclerView.setLayoutManager(new LinearLayoutManager(this));
        recyclerView.setAdapter(flashcardAdapter);

        // Initialize the new repository
        flashcardRepository = new FlashcardRepository(
            FlashcardRoomDatabase.getDatabase(getApplicationContext()).flashcardDao()
        );

        // Load initial data (future questions ascending)
        loadFlashcards(true);

        toggleReviewTime.setOnCheckedChangeListener((buttonView, isChecked) -> {
            // Show past or future
            loadFlashcards(!isChecked ? true : false);
        });
    }

    private void loadFlashcards(boolean showFuture) {
        flashcards.clear();
        // We'll fetch from the repository in a coroutine
        lifecycleScope.launch {
            List<Flashcard> list;
            if (showFuture) {
                list = withContext(Dispatchers.IO) {
                    return@withContext flashcardRepository.getFutureFlashcards(System.currentTimeMillis());
                };
            } else {
                list = withContext(Dispatchers.IO) {
                    return@withContext flashcardRepository.getPastFlashcards(System.currentTimeMillis());
                };
            }
            flashcards.addAll(list);
            flashcardAdapter.notifyDataSetChanged();
        };
    }
}

