package com.example.flashcardapp.main;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.TextView;
import android.widget.Toast;
import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AppCompatActivity;
import androidx.lifecycle.lifecycleScope;

import com.example.flashcardapp.R;
import com.example.flashcardapp.data.Flashcard;
import com.example.flashcardapp.data.FlashcardRepository;
import com.example.flashcardapp.data.FlashcardRoomDatabase;
import com.example.flashcardapp.main.TimeUtils;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

import kotlinx.coroutines.Dispatchers;
import kotlinx.coroutines.launch;
import kotlinx.coroutines.withContext;

public class ReviewFlashcardsActivity extends AppCompatActivity {

    private int totalQuestionsCount = 0;
    private int questionsMovedCount = 0;
    private int score = 0;

    private TextView tvTotalQuestions, tvQuestionsMoved, tvPast, tvFuture;
    private TextView tvQuestion, tvAnswer;
    private Button btnShowAnswer;
    private Button btnForgot, btnStruggling, btnUnsure, btnOkay, btnGood, btnPerfect;

    private Flashcard currentFlashcard;
    private long answerStartTime;

    private Set<Integer> seenFlashcards = new HashSet<>();

    // Use the new repository
    private FlashcardRepository flashcardRepository;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_review_flashcards);

        tvTotalQuestions = findViewById(R.id.tv_total_questions);
        tvQuestionsMoved = findViewById(R.id.tv_questions_moved);
        tvPast = findViewById(R.id.tv_past_questions);
        tvFuture = findViewById(R.id.tv_future_questions);
        tvQuestion = findViewById(R.id.tv_question);
        tvAnswer = findViewById(R.id.tv_answer);
        btnShowAnswer = findViewById(R.id.btn_show_answer);
        btnForgot = findViewById(R.id.btn_forgot);
        btnStruggling = findViewById(R.id.btn_struggling);
        btnUnsure = findViewById(R.id.btn_unsure);
        btnOkay = findViewById(R.id.btn_okay);
        btnGood = findViewById(R.id.btn_good);
        btnPerfect = findViewById(R.id.btn_perfect);

        findViewById(R.id.low_confidence_buttons).setVisibility(View.GONE);
        findViewById(R.id.high_confidence_buttons).setVisibility(View.GONE);

        // Initialize the new approach
        flashcardRepository = new FlashcardRepository(
            FlashcardRoomDatabase.getDatabase(getApplicationContext()).flashcardDao()
        );

        showNextFlashcard();

        tvQuestion.setOnClickListener(v -> openEditQuestion());

        btnShowAnswer.setOnClickListener(v -> {
            if (currentFlashcard != null) {
                tvAnswer.setText(currentFlashcard.getAnswer());
                tvAnswer.setVisibility(View.VISIBLE);
                btnShowAnswer.setVisibility(View.GONE);
                answerStartTime = System.nanoTime();
                findViewById(R.id.low_confidence_buttons).setVisibility(View.VISIBLE);
                findViewById(R.id.high_confidence_buttons).setVisibility(View.VISIBLE);
            }
        });

        btnForgot.setOnClickListener(v -> handleConfidence(0));
        btnStruggling.setOnClickListener(v -> handleConfidence(1));
        btnUnsure.setOnClickListener(v -> handleConfidence(2));
        btnOkay.setOnClickListener(v -> handleConfidence(3));
        btnGood.setOnClickListener(v -> handleConfidence(4));
        btnPerfect.setOnClickListener(v -> handleConfidence(5));
    }

    private void showNextFlashcard() {
        // We'll get the next card using a coroutine.
        lifecycleScope.launch {
            Flashcard nextCard = withContext(Dispatchers.IO) {
                return@withContext flashcardRepository.getNextDueFlashcard(System.currentTimeMillis());
            };
            if (nextCard != null) {
                currentFlashcard = nextCard;
                tvQuestion.setText(nextCard.getQuestion());
                tvAnswer.setVisibility(View.GONE);
                findViewById(R.id.low_confidence_buttons).setVisibility(View.GONE);
                findViewById(R.id.high_confidence_buttons).setVisibility(View.GONE);
                btnShowAnswer.setVisibility(View.VISIBLE);

                seenFlashcards.add(nextCard.getId());
                totalQuestionsCount++;
                updateCounters();
            } else {
                Toast.makeText(
                    ReviewFlashcardsActivity.this,
                    "No flashcards due for review!",
                    Toast.LENGTH_SHORT
                ).show();
                finish();
            }
        };
    }

    private void handleConfidence(int quality) {
        if (currentFlashcard == null) {
            return;
        }
        long duration = (System.nanoTime() - answerStartTime) / 1_000_000;

        // We do a minimal adaptation so that we still store the updated intervals.
        // For advanced review logging, add queries or new fields in the Room-based approach.

        // Calculate updated interval, nextReview, etc.
        updateFlashcardAfterReview(currentFlashcard, quality);
        long pushedMillis = currentFlashcard.getNextReview() - System.currentTimeMillis();
        String timeDiff = TimeUtils.formatTimeDifference(pushedMillis);
        Toast.makeText(this, "Next: " + timeDiff, Toast.LENGTH_LONG).show();
        if (pushedMillis > 24L * 60 * 60 * 1000) {
            questionsMovedCount++;
        }
        score += quality;
        updateCounters();
        showNextFlashcard();
    }

    private void updateFlashcardAfterReview(Flashcard flashcard, int quality) {
        long currentTime = System.currentTimeMillis();
        long lastReviewTime = flashcard.getNextReview() - (flashcard.getInterval() * 1000L);
        int interval = flashcard.getInterval();
        int repetition = flashcard.getRepetition();

        switch (quality) {
            case 0:
                interval = 1;
                repetition = 0;
                break;
            case 1:
                interval = 10;
                repetition = 0;
                break;
            case 2:
                interval = 20;
                repetition = 0;
                break;
            case 3:
                interval = 30;
                repetition += 1;
                break;
            case 4:
                interval = 1600;
                repetition += 1;
                break;
            case 5:
                long timeLapsed = (currentTime - lastReviewTime) / 1000;
                interval = (int)(timeLapsed * 2) + 3600;
                repetition++;
                break;
            default:
                interval = 30;
                repetition = 0;
                break;
        }

        long nextReview = currentTime + interval * 1000L;
        flashcard.setInterval(interval);
        flashcard.setNextReview(nextReview);
        flashcard.setRepetition(repetition);

        lifecycleScope.launch {
            withContext(Dispatchers.IO) {
                flashcardRepository.updateFlashcard(flashcard);
            }
        };
    }

    private void updateCounters() {
        lifecycleScope.launch {
            int[] counts = withContext(Dispatchers.IO) {
                return flashcardRepository.getPastAndFutureQuestionsCount(System.currentTimeMillis());
            };
            tvTotalQuestions.setText(String.valueOf(seenFlashcards.size()));
            tvQuestionsMoved.setText(String.valueOf(questionsMovedCount));
            tvPast.setText(String.valueOf(counts[0]));
            tvFuture.setText(String.valueOf(counts[1]));
        };
    }

    private final ActivityResultLauncher<Intent> editFlashcardLauncher =
        registerForActivityResult(
            new ActivityResultContracts.StartActivityForResult(),
            result -> {
                if (result.getResultCode() == RESULT_OK && currentFlashcard != null) {
                    lifecycleScope.launch {
                        Flashcard updated = withContext(Dispatchers.IO) {
                            return@withContext flashcardRepository.getFlashcardById(currentFlashcard.getId());
                        };
                        currentFlashcard = updated;
                    };
                }
            }
        );

    private void openEditQuestion() {
        if (currentFlashcard != null) {
            Intent intent = new Intent(this, EditFlashcardActivity.class);
            intent.putExtra("FLASHCARD_ID", currentFlashcard.getId());
            editFlashcardLauncher.launch(intent);
        }
    }
}

