package com.example.flashcardapp.main;

import android.os.Bundle;
import android.widget.Button;

import androidx.appcompat.app.AppCompatActivity;
import androidx.lifecycle.lifecycleScope;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.flashcardapp.R;
import com.example.flashcardapp.data.FlashcardRepository;
import com.example.flashcardapp.data.FlashcardRoomDatabase;
import com.example.flashcardapp.data.Topic;

import java.util.List;

import kotlinx.coroutines.Dispatchers;
import kotlinx.coroutines.launch;
import kotlinx.coroutines.withContext;

public class TopicSelectionActivity extends AppCompatActivity {

    private TopicSelectionAdapter adapter;
    private FlashcardRepository flashcardRepository;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_topic_selection);

        // Remove old FlashcardDAO references, using the new repository.
        flashcardRepository = new FlashcardRepository(
            FlashcardRoomDatabase.getDatabase(getApplicationContext()).flashcardDao()
        );

        RecyclerView rvTopics = findViewById(R.id.rv_topics);
        Button btnSave = findViewById(R.id.btn_save);
        rvTopics.setLayoutManager(new LinearLayoutManager(this));

        // Load topics from the repository (IO thread)
        lifecycleScope.launch {
            List<Topic> allTopics = withContext(Dispatchers.IO) {
                return@withContext flashcardRepository.getAllTopics();
            };
            adapter = new TopicSelectionAdapter(allTopics);
            rvTopics.setAdapter(adapter);
        };

        btnSave.setOnClickListener(v -> {
            lifecycleScope.launch {
                for (Topic topic : adapter.getSelectedTopics()) {
                    withContext(Dispatchers.IO) {
                        flashcardRepository.updateTopicSelection(topic.getId(), topic.isSelected());
                    }
                }
                finish();
            };
        });
    }
}
